    {
      "line": 2,
      "topic": "team habit ownership",
      "impact": 1,
      "assumption": "All team members are required to maintain their habit and track it through their streaks."
    },
    {
      "line": 3,
      "topic": "day boundary",
      "impact": 1,
      "assumption": "A user can complete a habit on their designated day, which becomes part of their streak, and they are not required to complete it on other days."
    },
    {
      "line": 4,
      "topic": "missed-day grace",
      "impact": 1,
      "assumption": "A user can complete a habit on a missed day by extending the grace period, which is part of their streak."
    },
    {
      "line": 5,
      "topic": "team habit ownership",
      "impact": 1,
      "assumption": "Team members share their habits and track progress across all team members."
    },
    {
      "line": 6,
      "topic": "historical edits",
      "impact": 1,
      "assumption": "Users can edit past check-ins by providing the necessary details and updating the information."
    },
    {
      "line": 7,
      "topic": "notification delivery",
      "impact": 1,
      "assumption": "Notifications are sent to the user's device and team members when their streak is at risk."
    }
  ]
